@RestController
public class OrderController {

    private final RestClient restClient;

    public OrderController(RestClient restClient) {
        this.restClient = restClient;
    }

    @GetMapping("/orders/{id}")
    public Order getOrder(@PathVariable String id) {
        // Written in a blocking, imperative style, but runs safely on a Virtual Thread
        // without consuming a precious OS thread while waiting for network I/O.
        return restClient.get()
                .uri("/api/v1/orders/" + id)
                .retrieve()
                .body(Order.class);
    }
}
